    "stalledLine": "「我沒有每一場都去。今天想說的是，那四個人聽完了。還有這次去書店的路線，我已經排好，不用你替我問。」「之前的工作還沒談好，今天這件小事不用算成已經和好了。」",
    "caseContext": "幾封邀請夾在書裡，去過和沒去過的分開。溫言特別挑一封，說那次不是害怕，是真的不想參加，希望也被記住。修復刷泡在杯中，今天有時間慢慢看。你不想把每封沒去的信都改成下一個練習，先聽他說哪幾次其實還想去。信不用今天回完。",
