    "ethicsContext": "有人要求把決定交還溫言本人。你先前越過別人意願的做法，仍讓合作的人不放心。",
    "ethicsEnding": "溫言親自確認後續安排。先前被你越過意願的人仍有疑問，這次親近沒有替那些事取得原諒。",
    "caseExit": "「邀請信我不代看，今天只確認朗讀要用的書。」",
